package io.github.vitarecomps.frontend;
import android.app.Activity;import android.content.Intent;import android.os.*;import android.net.Uri;import android.database.Cursor;import android.provider.OpenableColumns;import java.io.*;import java.nio.file.*;import java.util.*;import org.libsdl.app.SDLActivity;
public class FrontendStepActivity extends GameActivity {
 public static final String EXTRA_EXIT_CODE="exit_code";private final List<ParcelFileDescriptor> picked=new ArrayList<>();private String[] prepared;private String importError;
 private String name(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&c.getString(0)!=null)return c.getString(0);}catch(Exception e){ImportDiagnostics.note(this,"Nome do documento indisponivel: "+e);}return uri.getLastPathSegment()!=null?uri.getLastPathSegment():"arquivo";}
 private void check(File f)throws IOException{try(RandomAccessFile p=new RandomAccessFile(f,"r")){if(p.length()==0)throw new IOException("O arquivo esta vazio");p.seek(0);if(p.read()<0)throw new IOException("Nao foi possivel ler o arquivo");p.seek(0);}}
 private File local(Uri uri,String extension,int i,long size)throws IOException{File dir=new File(getCacheDir(),"import-staging");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Nao foi possivel criar a pasta temporaria");if(size>0&&dir.getUsableSpace()<size+67108864L)throw new IOException("Espaco insuficiente para copiar o arquivo: "+size+" bytes");File temp=new File(dir,"picked-"+i+extension+".part"),dest=new File(dir,"picked-"+i+extension);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("Android nao forneceu acesso de leitura");byte[] buf=new byte[1048576];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}catch(IOException e){temp.delete();throw e;}Files.move(temp.toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);check(dest);ImportDiagnostics.note(this,"Copia local preparada: "+dest.getName()+", "+dest.length()+" bytes");return dest;}
 @Override protected String[] getArguments(){if(prepared!=null)return prepared;String[] args=super.getArguments().clone();for(int i=0;i<args.length;i++){if(!args[i].startsWith("content://"))continue;Uri uri=Uri.parse(args[i]);String display=name(uri);int dot=display.lastIndexOf('.');String extension=dot>=0?display.substring(dot).toLowerCase(Locale.ROOT):"";ParcelFileDescriptor fd=null;try{ImportDiagnostics.note(this,"Abrindo documento "+display+" como argumento "+i);if(extension.length()>12||!extension.matches("\\.[a-z0-9]+"))throw new IOException("Extensao nao reconhecida: "+display);fd=getContentResolver().openFileDescriptor(uri,"r");if(fd==null)throw new IOException("Android retornou descritor de arquivo nulo");long size=fd.getStatSize();if(size==0)throw new IOException("Arquivo vazio: "+display);if(extension.equals(".bin")||extension.equals(".rif")){File f=local(uri,extension,i,size);args[i]=f.getPath();fd.close();fd=null;continue;}File link=new File(getCacheDir(),"picked-"+i+extension);try{if(link.exists()&&!link.delete())throw new IOException("Nao foi possivel substituir o caminho temporario");android.system.Os.symlink("/proc/self/fd/"+fd.getFd(),link.getPath());check(link);args[i]=link.getPath();picked.add(fd);fd=null;ImportDiagnostics.note(this,"Acesso direto validado: "+display+"; tamanho "+size);}catch(Exception bridge){ImportDiagnostics.note(this,"Ponte por descritor falhou para "+display+": "+bridge+"; tentando copia local");File f=local(uri,extension,i,size);args[i]=f.getPath();}}catch(Exception e){importError="Nao foi possivel preparar "+display+": "+e.getClass().getSimpleName()+": "+e.getMessage();ImportDiagnostics.note(this,importError);break;}finally{if(fd!=null)try{fd.close();}catch(IOException ignored){}}}prepared=args;return args;}
 @Override protected void main(){int code=1;String[] args=getArguments();if(importError==null){try{ImportDiagnostics.note(this,"Iniciando etapa nativa; arquivos acessiveis.");code=SDLActivity.nativeRunMain(getMainSharedObject(),getMainFunction(),args);}catch(Throwable e){importError="Erro ao executar etapa nativa: "+e;ImportDiagnostics.note(this,importError);}}else ImportDiagnostics.note(this,"Etapa nativa NAO iniciada devido ao erro de acesso acima.");ImportDiagnostics.note(this,"Codigo de saida da etapa: "+code);Intent result=new Intent().putExtra(EXTRA_EXIT_CODE,code);if(importError!=null)result.putExtra("import_error",importError);setResult(code==0?Activity.RESULT_OK:Activity.RESULT_FIRST_USER+code,result);}
 @Override protected void onDestroy(){super.onDestroy();if(isFinishing())new Handler(Looper.getMainLooper()).postDelayed(()->android.os.Process.killProcess(android.os.Process.myPid()),300);}
}
